/// <summary>
/// Gets or sets the number of threads.
/// </summary>
/// <param name="_noOfThreads">The number of threads to be used for processing.</param>
/// <returns>The number of threads.</returns>
[DataMemberAttribute,
SysOperationLabelAttribute("@SYS109551")]
public int parmNoOfThreads(int _noOfThreads = noOfThreads)
{
    noOfThreads = _noOfThreads;

    return noOfThreads;
}

/// <summary>
/// Gets or sets the packed query string.
/// </summary>
/// <param name="_packedQuery">The packed query string used for the operation.</param>
/// <returns>The packed query string.</returns>
[DataMemberAttribute, AifQueryTypeAttribute('_packedQuery', queryStr(METRejectedFreeTextInvoice))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}
